CREATE TABLE projects(id TEXT PRIMARY KEY,title TEXT NOT NULL,settings_json TEXT NOT NULL DEFAULT '{}',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE assets(sha256 TEXT PRIMARY KEY,relative_path TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL);
CREATE TABLE reference_sets(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,stable_key TEXT NOT NULL,current_revision_id TEXT,UNIQUE(project_id,kind,stable_key));
CREATE TABLE reference_revisions(id TEXT PRIMARY KEY,reference_id TEXT NOT NULL REFERENCES reference_sets(id),metadata_json TEXT NOT NULL,asset_hashes_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE pages(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),number INTEGER NOT NULL CHECK(number>0),draft_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,latest_round_id TEXT REFERENCES rounds(id),accepted_candidate_id TEXT REFERENCES candidates(id),UNIQUE(project_id,number));
CREATE TABLE rounds(id TEXT PRIMARY KEY,page_id TEXT NOT NULL REFERENCES pages(id),sequence INTEGER NOT NULL,input_hash TEXT NOT NULL,snapshot_json TEXT NOT NULL,prompt_text TEXT NOT NULL,review_state TEXT NOT NULL DEFAULT 'pending',rejection_reason TEXT,created_at TEXT NOT NULL,UNIQUE(page_id,sequence));
CREATE TABLE plans(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),payload_json TEXT NOT NULL,expires REAL NOT NULL);
CREATE TABLE batches(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,idempotency_key TEXT NOT NULL,payload_hash TEXT NOT NULL,plan_json TEXT NOT NULL,cap_micro INTEGER NOT NULL CHECK(cap_micro>=0),unit_reserve_micro INTEGER NOT NULL CHECK(unit_reserve_micro>0),spent_reserved_micro INTEGER NOT NULL DEFAULT 0,paused INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,UNIQUE(project_id,idempotency_key));
CREATE TABLE jobs(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES batches(id),round_id TEXT NOT NULL REFERENCES rounds(id),candidate_index INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'queued',active_attempt_id TEXT REFERENCES attempts(id),retry_after REAL NOT NULL DEFAULT 0,manual_allowance INTEGER NOT NULL DEFAULT 0,UNIQUE(round_id,candidate_index));
CREATE TABLE chunks(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES batches(id),attempt_no INTEGER NOT NULL DEFAULT 1,state TEXT NOT NULL,display_key TEXT NOT NULL UNIQUE,payload_path TEXT,payload_hash TEXT,remote_name TEXT,input_remote_name TEXT,output_path TEXT,next_poll_at REAL NOT NULL DEFAULT 0,last_error TEXT,fetch_failures INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE attempts(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),chunk_id TEXT NOT NULL REFERENCES chunks(id),request_key TEXT NOT NULL UNIQUE,state TEXT NOT NULL,send_reserved_micro INTEGER NOT NULL,error_code TEXT,usage_json TEXT,created_at TEXT NOT NULL);
CREATE TABLE candidates(id TEXT PRIMARY KEY,job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id),attempt_id TEXT NOT NULL REFERENCES attempts(id),asset_hash TEXT NOT NULL REFERENCES assets(sha256),thumbnail_hash TEXT NOT NULL REFERENCES assets(sha256),raw_asset_hash TEXT NOT NULL REFERENCES assets(sha256),availability TEXT NOT NULL DEFAULT 'available',created_at TEXT NOT NULL);
CREATE TABLE review_events(id TEXT PRIMARY KEY,page_id TEXT NOT NULL REFERENCES pages(id),round_id TEXT NOT NULL REFERENCES rounds(id),candidate_id TEXT REFERENCES candidates(id),decision TEXT NOT NULL,reason TEXT,created_at TEXT NOT NULL);
CREATE TABLE exports(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),manifest_json TEXT NOT NULL,archive_path TEXT,state TEXT NOT NULL,created_at TEXT NOT NULL,error TEXT);
CREATE TABLE mutation_receipts(scope TEXT NOT NULL,idempotency_key TEXT NOT NULL,payload_hash TEXT NOT NULL,response_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(scope,idempotency_key));
CREATE TABLE audit_events(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),action TEXT NOT NULL,target_id TEXT,before_json TEXT,after_json TEXT,created_at TEXT NOT NULL);
CREATE TABLE system(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE INDEX jobs_state ON jobs(state,retry_after);
CREATE INDEX chunks_state ON chunks(state,next_poll_at);
CREATE INDEX page_rounds ON rounds(page_id,sequence);
CREATE INDEX attempts_job ON attempts(job_id);
